<?php
session_start();require '../config/database.php'; require '../lib_security.php';if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: ../login.php');exit;}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$sid=(int)$_POST['student_id'];$type=$_POST['certificate_type'];$purpose=trim($_POST['purpose']??'');if(!in_array($type,['bonafide','character','enrollment'],true)){$msg='Invalid certificate type.';}else{$no='CERT-IMCB-'.date('Y').'-'.str_pad((string)random_int(1,99999),5,'0',STR_PAD_LEFT);$q=$pdo->prepare('INSERT INTO student_certificates(student_id,certificate_type,purpose,certificate_no,issue_date) VALUES(?,?,?,?,?)');$q->execute([$sid,$type,$purpose,$no,date('Y-m-d')]);$msg='Certificate generated successfully.';}}
$students=$pdo->query('SELECT st.id,st.roll_no,u.name,p.name program_name FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id ORDER BY u.name')->fetchAll();$certs=$pdo->query('SELECT c.*,u.name,st.roll_no FROM student_certificates c JOIN students st ON st.id=c.student_id JOIN users u ON u.id=st.user_id ORDER BY c.issue_date DESC,c.id DESC')->fetchAll();$pageTitle='Certificates';require '../includes/header.php';?><div class="container-fluid"><div class="row"><aside class="col-md-2 sidebar py-4"><h6 class="px-3 text-muted">ADMIN MENU</h6><a href="../admin.php">Dashboard</a><a class="active" href="certificates.php">Certificates</a><a href="id_cards.php">Student ID Cards</a><a href="documents.php">Document Verification</a></aside><main class="col-md-10 p-4"><h2 class="fw-bold">Certificates</h2><?php if($msg):?><div class="alert alert-success"><?=htmlspecialchars($msg)?></div><?php endif;?><div class="card shadow-sm border-0 mb-4"><div class="card-body"><form method="post" class="row g-3"><?php echo csrfField(); ?><div class="col-md-5"><label class="form-label">Student</label><select name="student_id" class="form-select" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'].' — '.$s['roll_no'].' — '.$s['program_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Certificate</label><select name="certificate_type" class="form-select"><option value="bonafide">Bonafide</option><option value="character">Character</option><option value="enrollment">Enrollment</option></select></div><div class="col-md-3"><label class="form-label">Purpose</label><input name="purpose" class="form-control"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Generate</button></div></form></div></div><div class="card shadow-sm border-0"><div class="card-body"><table class="table"><thead><tr><th>Student</th><th>Type</th><th>Certificate No</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($certs as $c):?><tr><td><?=htmlspecialchars($c['name'].' — '.$c['roll_no'])?></td><td><?=htmlspecialchars(ucfirst($c['certificate_type']))?></td><td><?=htmlspecialchars($c['certificate_no'])?></td><td><?=htmlspecialchars($c['issue_date'])?></td><td><a target="_blank" href="../certificate.php?id=<?=$c['id']?>" class="btn btn-sm btn-outline-primary">Print</a></td></tr><?php endforeach;if(!$certs):?><tr><td colspan="5" class="text-muted">No certificates generated.</td></tr><?php endif;?></tbody></table></div></div></main></div></div><?php require '../includes/footer.php';?>
